{
    int ret = 0, i;
    AVFormatContext *is, *os;
    AVCodecContext *codec, *icodec;
    OutputStream *ost;
    InputStream *ist;
    char error[1024];
    int want_sdp = 1;
    uint8_t *no_packet;
    int no_packet_count=0;
    int64_t timer_start;

    if (!(no_packet = av_mallocz(nb_input_files)))
        exit_program(1);

    if (rate_emu)
